@namespace sv_0e35cef357644a739eb69da0b08be41a.Components.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Services.Channel> Channels { get; set; } = new();
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    background-color: #2f3136;
    height: 100%;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@namespace sv_0e35cef357644a739eb69da0b08be41a.Components.Chat
@using sv_0e35cef357644a739eb69da0b08be41a.Services
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        @if (Channel is not null)
        {
            <h2># @Channel.Name</h2>
            <span class="channel-desc">@Channel.Description</span>
        }
    </div>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name ?? "channel"}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private bool _shouldScrollToBottom = true;

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 1 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_shouldScrollToBottom)
        {
            await JS.InvokeVoidAsync("eval",
                "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
            _shouldScrollToBottom = false;
        }
    }

    public void ScrollToBottom() => _shouldScrollToBottom = true;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    overflow: hidden;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
    display: flex;
    align-items: baseline;
    gap: 12px;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.channel-desc {
    font-size: 0.85rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 0.85rem;
}

@namespace sv_0e35cef357644a739eb69da0b08be41a.Components.Chat
@using sv_0e35cef357644a739eb69da0b08be41a.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <span class="quote-author">@RootMessage.Author</span>
            <p class="quote-content">@RootMessage.Content</p>
        </div>
    }

    <div class="thread-messages">
        @foreach (var msg in Replies)
        {
            <MessageItem Message="msg"
                         ReplyCount="0"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonLabel="Reply"
                  OnSend="OnSendReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    border-left: 1px solid #3f4147;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background-color: rgba(0, 0, 0, 0.1);
    border-left: 3px solid #5865f2;
    margin: 8px 12px;
