@page "/chat"
@layout sv_0e35cef357644a739eb69da0b08be41a.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_0e35cef357644a739eb69da0b08be41a.Components.Chat
@using sv_0e35cef357644a739eb69da0b08be41a.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar-col">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main-col @(_isThreadOpen ? "" : "expanded")">
        <MessageArea @ref="_messageArea"
                     Channel="_selectedChannel"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (_isThreadOpen)
    {
        <div class="chat-thread-col">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<Message> _threadReplies = new();
    private Dictionary<int, int> _threadReplyCounts = new();
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private Message? _threadRootMessage;
    private bool _isThreadOpen;
    private bool _isLoadingMore;
    private int _skip;
    private const int PageSize = 50;
    private MessageArea? _messageArea;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        _channels = await ChatService.GetChannelsAsync();
        await ComputeThreadReplyCounts();
        CloseThreadInternal();
        _messageArea?.ScrollToBottom();
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
        _messageArea?.ScrollToBottom();
    }

    private async Task OpenThread(int rootMessageId)
    {
        var thread = await ChatService.GetThreadAsync(rootMessageId);
        _threadRootMessage = thread.FirstOrDefault();
        _threadReplies = thread.Skip(1).ToList();
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        CloseThreadInternal();
    }

    private void CloseThreadInternal()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        await ComputeThreadReplyCounts();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _skip + PageSize);
        if (_threadRootMessage is not null)
        {
            var thread = await ChatService.GetThreadAsync(_threadRootMessage.Id);
            _threadRootMessage = thread.FirstOrDefault();
            _threadReplies = thread.Skip(1).ToList();
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null || _isLoadingMore) return;
        _isLoadingMore = true;
        StateHasChanged();

        _skip += PageSize;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _skip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
        }
        _isLoadingMore = false;
    }

    private async Task ComputeThreadReplyCounts()
    {
        _threadReplyCounts = new();
        foreach (var msg in _messages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            var replyCount = thread.Count - 1; // exclude root
            if (replyCount > 0)
                _threadReplyCounts[msg.Id] = replyCount;
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    background-color: #36393f;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
}

.chat-sidebar-col {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main-col {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main-col.expanded {
    flex: 1;
}

.chat-thread-col {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

::deep * {
    box-sizing: border-box;
}

